const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const mod = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
        .link_libc = true,
    });
    // SQLite ships with macOS and every mainstream Linux distribution.
    mod.linkSystemLibrary("sqlite3", .{});

    const exe = b.addExecutable(.{ .name = "notes", .root_module = mod });
    b.installArtifact(exe);

    const run_cmd = b.addRunArtifact(exe);
    run_cmd.step.dependOn(b.getInstallStep());
    if (b.args) |args| run_cmd.addArgs(args);
    b.step("run", "Run the server").dependOn(&run_cmd.step);

    const tests = b.addTest(.{ .root_module = mod });
    b.step("test", "Run unit tests").dependOn(&b.addRunArtifact(tests).step);
}

//! Persistent note storage on a single SQLite connection.
//!
//! All operations serialize on one mutex: SQLite allows only one writer at a
//! time anyway, and a single connection keeps transactions simple.

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;
const sqlite = @import("sqlite.zig");
const Note = @import("note.zig").Note;
const Input = @import("note.zig").Input;

const Store = @This();

db: sqlite.Db,
mutex: Io.Mutex = .init,
io: Io,

pub const Error = sqlite.Error || Allocator.Error;

const schema =
    \\PRAGMA journal_mode = WAL;
    \\PRAGMA synchronous = NORMAL;
    \\PRAGMA foreign_keys = ON;
    \\PRAGMA busy_timeout = 5000;
    \\CREATE TABLE IF NOT EXISTS notes (
    \\    id    INTEGER PRIMARY KEY AUTOINCREMENT,
    \\    title TEXT NOT NULL,
    \\    body  TEXT NOT NULL
    \\);
    \\CREATE TABLE IF NOT EXISTS note_tags (
    \\    note_id INTEGER NOT NULL REFERENCES notes(id) ON DELETE CASCADE,
    \\    tag     TEXT NOT NULL,
    \\    PRIMARY KEY (note_id, tag)
    \\) WITHOUT ROWID;
    \\CREATE INDEX IF NOT EXISTS note_tags_by_tag ON note_tags(tag, note_id);
;

pub fn open(io: Io, path: [:0]const u8) sqlite.Error!Store {
    const db = try sqlite.Db.open(path);
    errdefer db.close();
    try db.exec(schema);
    return .{ .db = db, .io = io };
}

pub fn close(s: *Store) void {
    s.db.close();
}

fn lock(s: *Store) void {
    s.mutex.lockUncancelable(s.io);
}

fn unlock(s: *Store) void {
    s.mutex.unlock(s.io);
}

/// Runs `body` inside a write transaction, rolling back if it fails.
fn transaction(s: *Store, comptime T: type, body: anytype, args: anytype) Error!T {
    try s.db.exec("BEGIN IMMEDIATE");
    const result = @call(.auto, body, args) catch |err| {
        s.db.exec("ROLLBACK") catch {};
        return err;
    };
    try s.db.exec("COMMIT");
    return result;
}

pub fn create(s: *Store, gpa: Allocator, input: Input) Error!Note {
    s.lock();
    defer s.unlock();
    const id = try s.transaction(i64, createTx, .{ s, input });
    return .{ .id = id, .title = try gpa.dupe(u8, input.title), .body = try gpa.dupe(u8, input.body), .tags = try dupeTags(gpa, input.tags) };
}

fn createTx(s: *Store, input: Input) Error!i64 {
    const stmt = try s.db.prepare("INSERT INTO notes (title, body) VALUES (?, ?)");
    defer stmt.finalize();
    try stmt.bindAll(.{ input.title, input.body });
    _ = try stmt.step();
    const id = s.db.lastInsertRowId();
    try s.insertTags(id, input.tags);
    return id;
}

/// Replaces the note's content; returns null when the note does not exist.
pub fn update(s: *Store, gpa: Allocator, id: i64, input: Input) Error!?Note {
    s.lock();
    defer s.unlock();
    if (!try s.transaction(bool, updateTx, .{ s, id, input })) return null;
    return .{ .id = id, .title = try gpa.dupe(u8, input.title), .body = try gpa.dupe(u8, input.body), .tags = try dupeTags(gpa, input.tags) };
}

fn updateTx(s: *Store, id: i64, input: Input) Error!bool {
    {
        const stmt = try s.db.prepare("UPDATE notes SET title = ?, body = ? WHERE id = ?");
        defer stmt.finalize();
        try stmt.bindAll(.{ input.title, input.body, id });
        _ = try stmt.step();
        if (s.db.changes() == 0) return false;
    }
    {
        const stmt = try s.db.prepare("DELETE FROM note_tags WHERE note_id = ?");
        defer stmt.finalize();
        try stmt.bind(1, id);
        _ = try stmt.step();
    }
    try s.insertTags(id, input.tags);
    return true;
}

fn insertTags(s: *Store, id: i64, tags: []const []const u8) Error!void {
    if (tags.len == 0) return;
    const stmt = try s.db.prepare("INSERT OR IGNORE INTO note_tags (note_id, tag) VALUES (?, ?)");
    defer stmt.finalize();
    for (tags) |tag| {
        try stmt.reset();
        try stmt.bindAll(.{ id, tag });
        _ = try stmt.step();
    }
}

/// Deletes a note; returns false when it does not exist.
pub fn delete(s: *Store, id: i64) Error!bool {
    s.lock();
    defer s.unlock();
    const stmt = try s.db.prepare("DELETE FROM notes WHERE id = ?");
    defer stmt.finalize();
    try stmt.bind(1, id);
    _ = try stmt.step();
    return s.db.changes() > 0;
}

pub fn get(s: *Store, gpa: Allocator, id: i64) Error!?Note {
    s.lock();
    defer s.unlock();
    const stmt = try s.db.prepare("SELECT id, title, body FROM notes WHERE id = ?");
    defer stmt.finalize();
    try stmt.bind(1, id);
    if (!try stmt.step()) return null;

    const tags_stmt = try s.prepareTags();
    defer tags_stmt.finalize();
    return try readNote(gpa, stmt, tags_stmt);
}

pub const Filter = struct {
    tag: ?[]const u8 = null,
    /// Case-insensitive (ASCII) substring of title or body.
    query: ?[]const u8 = null,
    after: i64 = 0,
    limit: usize = 100,
};

/// Notes matching `filter`, ordered by id ascending.
pub fn list(s: *Store, gpa: Allocator, filter: Filter) Error![]Note {
    s.lock();
    defer s.unlock();

    const stmt = if (filter.tag) |tag| blk: {
        const st = try s.db.prepare(
            \\SELECT n.id, n.title, n.body FROM notes n
            \\JOIN note_tags t ON t.note_id = n.id
            \\WHERE t.tag = ? AND n.id > ? ORDER BY n.id
        );
        errdefer st.finalize();
        try st.bindAll(.{ tag, filter.after });
        break :blk st;
    } else blk: {
        const st = try s.db.prepare("SELECT id, title, body FROM notes WHERE id > ? ORDER BY id");
        errdefer st.finalize();
        try st.bind(1, filter.after);
        break :blk st;
    };
    defer stmt.finalize();

    const tags_stmt = try s.prepareTags();
    defer tags_stmt.finalize();

    var notes: std.ArrayList(Note) = .empty;
    errdefer notes.deinit(gpa);
    while (notes.items.len < filter.limit and try stmt.step()) {
        if (filter.query) |q| {
            if (!containsIgnoreCase(stmt.text(1), q) and !containsIgnoreCase(stmt.text(2), q)) continue;
        }
        try notes.append(gpa, try readNote(gpa, stmt, tags_stmt));
    }
    return notes.toOwnedSlice(gpa);
}

fn containsIgnoreCase(haystack: []const u8, needle: []const u8) bool {
    return std.ascii.indexOfIgnoreCase(haystack, needle) != null;
}

fn prepareTags(s: *Store) Error!sqlite.Stmt {
    return s.db.prepare("SELECT tag FROM note_tags WHERE note_id = ? ORDER BY tag");
}

/// Copies the current row of `stmt` (id, title, body) plus its tags into `gpa` memory.
fn readNote(gpa: Allocator, stmt: sqlite.Stmt, tags_stmt: sqlite.Stmt) Error!Note {
    const id = stmt.int(0);
    try tags_stmt.reset();
    try tags_stmt.bind(1, id);
    var tags: std.ArrayList([]const u8) = .empty;
    while (try tags_stmt.step()) try tags.append(gpa, try gpa.dupe(u8, tags_stmt.text(0)));
    return .{
        .id = id,
        .title = try gpa.dupe(u8, stmt.text(1)),
        .body = try gpa.dupe(u8, stmt.text(2)),
        .tags = try tags.toOwnedSlice(gpa),
    };
}

fn dupeTags(gpa: Allocator, tags: []const []const u8) Allocator.Error![]const []const u8 {
    const out = try gpa.alloc([]const u8, tags.len);
    for (tags, out) |tag, *slot| slot.* = try gpa.dupe(u8, tag);
    return out;
}

pub const TagCount = struct {
    tag: []const u8,
    count: i64,
};

/// Tags with the number of notes carrying them, by count descending then tag ascending.
pub fn tagCounts(s: *Store, gpa: Allocator) Error![]TagCount {
    s.lock();
    defer s.unlock();
    const stmt = try s.db.prepare(
        \\SELECT tag, COUNT(*) AS n FROM note_tags GROUP BY tag ORDER BY n DESC, tag ASC
    );
    defer stmt.finalize();
    var out: std.ArrayList(TagCount) = .empty;
    errdefer out.deinit(gpa);
    while (try stmt.step()) {
        try out.append(gpa, .{ .tag = try gpa.dupe(u8, stmt.text(0)), .count = stmt.int(1) });
    }
    return out.toOwnedSlice(gpa);
}

pub fn noteCount(s: *Store) Error!i64 {
    s.lock();
    defer s.unlock();
    const stmt = try s.db.prepare("SELECT COUNT(*) FROM notes");
    defer stmt.finalize();
    _ = try stmt.step();
    return stmt.int(0);
}

const testing = std.testing;

test "create, update, delete, list and count" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    var store = try Store.open(testing.io, ":memory:");
    defer store.close();

    const n1 = try store.create(a, .{ .title = "Hello", .body = "", .tags = &.{ "greet", "x" } });
    const n2 = try store.create(a, .{ .title = "other", .body = "say HELLO", .tags = &.{"x"} });
    _ = try store.create(a, .{ .title = "nothing", .body = "", .tags = &.{} });
    try testing.expectEqual(1, n1.id);
    try testing.expectEqual(2, n2.id);

    try testing.expectEqual(2, (try store.list(a, .{ .query = "hello" })).len);
    try testing.expectEqual(1, (try store.list(a, .{ .tag = "greet" })).len);
    try testing.expectEqual(1, (try store.list(a, .{ .after = 2 })).len);
    try testing.expectEqual(1, (try store.list(a, .{ .limit = 1 })).len);

    const counts = try store.tagCounts(a);
    try testing.expectEqual(2, counts.len);
    try testing.expectEqualStrings("x", counts[0].tag);
    try testing.expectEqual(2, counts[0].count);

    try testing.expect(try store.delete(1));
    try testing.expect(!try store.delete(1));
    try testing.expectEqual(null, try store.get(a, 1));
    try testing.expectEqual(null, try store.update(a, 1, .{ .title = "t", .body = "", .tags = &.{} }));

    const n4 = try store.create(a, .{ .title = "again", .body = "", .tags = &.{} });
    try testing.expectEqual(4, n4.id);
    try testing.expectEqual(3, try store.noteCount());
    try testing.expectEqual(1, (try store.tagCounts(a)).len);

    const upd = (try store.update(a, 2, .{ .title = "new", .body = "b", .tags = &.{"y"} })).?;
    try testing.expectEqualStrings("new", upd.title);
    const got = (try store.get(a, 2)).?;
    try testing.expectEqualStrings("y", got.tags[0]);
}

//! Request routing and the JSON API, independent of the HTTP transport.

const std = @import("std");
const http = std.http;
const Allocator = std.mem.Allocator;
const Store = @import("Store.zig");
const note = @import("note.zig");

pub const Response = struct {
    status: http.Status,
    body: []const u8,
    content_type: []const u8 = "application/json",
};

pub const Request = struct {
    method: http.Method,
    /// Request target: path plus optional `?query`.
    target: []const u8,
    body: []const u8 = "",
};

/// Handles one request. All allocations go to `arena`, which must outlive the response.
pub fn handle(store: *Store, arena: Allocator, req: Request) (Store.Error)!Response {
    const path, const query = splitTarget(req.target);

    if (std.mem.eql(u8, path, "/health")) {
        if (req.method != .GET) return methodNotAllowed();
        return .{ .status = .ok, .body = "ok", .content_type = "text/plain" };
    }
    if (std.mem.eql(u8, path, "/notes")) return switch (req.method) {
        .GET => listNotes(store, arena, query),
        .POST => createNote(store, arena, req.body),
        else => methodNotAllowed(),
    };
    if (std.mem.startsWith(u8, path, "/notes/")) {
        const rest = path["/notes/".len..];
        if (std.mem.indexOfScalar(u8, rest, '/') != null) return notFound();
        switch (req.method) {
            .GET, .PUT, .DELETE => {},
            else => return methodNotAllowed(),
        }
        const id = parseId(rest) orelse return notFound();
        return switch (req.method) {
            .GET => getNote(store, arena, id),
            .PUT => updateNote(store, arena, id, req.body),
            .DELETE => deleteNote(store, id),
            else => unreachable,
        };
    }
    if (std.mem.eql(u8, path, "/stats")) {
        if (req.method != .GET) return methodNotAllowed();
        return stats(store, arena);
    }
    if (std.mem.eql(u8, path, "/tags")) {
        if (req.method != .GET) return methodNotAllowed();
        return tags(store, arena);
    }
    return notFound();
}

fn splitTarget(target: []const u8) struct { []const u8, []const u8 } {
    if (std.mem.indexOfScalar(u8, target, '?')) |i| return .{ target[0..i], target[i + 1 ..] };
    return .{ target, "" };
}

fn errorResponse(status: http.Status, comptime message: []const u8) Response {
    return .{ .status = status, .body = "{\"error\":\"" ++ message ++ "\"}" };
}

fn notFound() Response {
    return errorResponse(.not_found, "not found");
}

fn methodNotAllowed() Response {
    return errorResponse(.method_not_allowed, "method not allowed");
}

fn badRequest(arena: Allocator, message: []const u8) Allocator.Error!Response {
    return .{ .status = .bad_request, .body = try json(arena, .{ .@"error" = message }) };
}

fn json(arena: Allocator, value: anytype) Allocator.Error![]const u8 {
    return std.json.Stringify.valueAlloc(arena, value, .{});
}

/// Parses a positive decimal note id made only of digits.
fn parseId(text: []const u8) ?i64 {
    if (text.len == 0) return null;
    for (text) |ch| if (!std.ascii.isDigit(ch)) return null;
    const id = std.fmt.parseInt(i64, text, 10) catch return null;
    return if (id > 0) id else null;
}

/// Parses an optionally negative decimal integer made only of digits.
fn parseInteger(text: []const u8) ?i64 {
    const digits = if (std.mem.startsWith(u8, text, "-")) text[1..] else text;
    if (digits.len == 0) return null;
    for (digits) |ch| if (!std.ascii.isDigit(ch)) return null;
    return std.fmt.parseInt(i64, text, 10) catch null;
}

/// Decodes an `application/x-www-form-urlencoded` component.
fn decodeComponent(arena: Allocator, raw: []const u8) Allocator.Error![]const u8 {
    const buf = try arena.dupe(u8, raw);
    std.mem.replaceScalar(u8, buf, '+', ' ');
    return std.Uri.percentDecodeInPlace(buf);
}

const ListParams = union(enum) {
    ok: Store.Filter,
    invalid: []const u8,
};

fn parseListParams(arena: Allocator, query: []const u8) Allocator.Error!ListParams {
    var filter: Store.Filter = .{};
    var it = std.mem.splitScalar(u8, query, '&');
    while (it.next()) |pair| {
        if (pair.len == 0) continue;
        const eq = std.mem.indexOfScalar(u8, pair, '=');
        const key = try decodeComponent(arena, pair[0 .. eq orelse pair.len]);
        const value = try decodeComponent(arena, if (eq) |i| pair[i + 1 ..] else "");
        if (std.mem.eql(u8, key, "tag")) {
            filter.tag = value;
        } else if (std.mem.eql(u8, key, "q")) {
            filter.query = value;
        } else if (std.mem.eql(u8, key, "after")) {
            filter.after = parseInteger(value) orelse return .{ .invalid = "after must be an integer" };
        } else if (std.mem.eql(u8, key, "limit")) {
            const n = parseInteger(value) orelse return .{ .invalid = "limit must be an integer from 1 to 100" };
            if (n < 1 or n > 100) return .{ .invalid = "limit must be an integer from 1 to 100" };
            filter.limit = @intCast(n);
        }
    }
    return .{ .ok = filter };
}

fn listNotes(store: *Store, arena: Allocator, query: []const u8) Store.Error!Response {
    const filter = switch (try parseListParams(arena, query)) {
        .ok => |f| f,
        .invalid => |msg| return badRequest(arena, msg),
    };
    const notes = try store.list(arena, filter);
    return .{ .status = .ok, .body = try json(arena, .{ .notes = notes }) };
}

fn createNote(store: *Store, arena: Allocator, body: []const u8) Store.Error!Response {
    const input = switch (try note.parseInput(arena, body)) {
        .ok => |in| in,
        .invalid => |msg| return badRequest(arena, msg),
    };
    const created = try store.create(arena, input);
    return .{ .status = .created, .body = try json(arena, created) };
}

fn getNote(store: *Store, arena: Allocator, id: i64) Store.Error!Response {
    const found = try store.get(arena, id) orelse return notFound();
    return .{ .status = .ok, .body = try json(arena, found) };
}

fn updateNote(store: *Store, arena: Allocator, id: i64, body: []const u8) Store.Error!Response {
    const input = switch (try note.parseInput(arena, body)) {
        .ok => |in| in,
        .invalid => |msg| return badRequest(arena, msg),
    };
    const updated = try store.update(arena, id, input) orelse return notFound();
    return .{ .status = .ok, .body = try json(arena, updated) };
}

fn deleteNote(store: *Store, id: i64) Store.Error!Response {
    if (!try store.delete(id)) return notFound();
    return .{ .status = .no_content, .body = "" };
}

fn stats(store: *Store, arena: Allocator) Store.Error!Response {
    const count = try store.noteCount();
    const counts = try store.tagCounts(arena);

    var out: std.Io.Writer.Allocating = .init(arena);
    var w: std.json.Stringify = .{ .writer = &out.writer };
    writeStats(&w, count, counts) catch return error.OutOfMemory;
    return .{ .status = .ok, .body = out.written() };
}

fn writeStats(w: *std.json.Stringify, count: i64, counts: []const Store.TagCount) std.json.Stringify.Error!void {
    try w.beginObject();
    try w.objectField("notes");
    try w.write(count);
    try w.objectField("tags");
    try w.beginObject();
    for (counts) |tc| {
        try w.objectField(tc.tag);
        try w.write(tc.count);
    }
    try w.endObject();
    try w.endObject();
}

fn tags(store: *Store, arena: Allocator) Store.Error!Response {
    const counts = try store.tagCounts(arena);
    return .{ .status = .ok, .body = try json(arena, .{ .tags = counts }) };
}

const testing = std.testing;

const TestEnv = struct {
    arena: std.heap.ArenaAllocator,
    store: Store,

    fn init() !TestEnv {
        return .{ .arena = .init(testing.allocator), .store = try Store.open(testing.io, ":memory:") };
    }

    fn deinit(env: *TestEnv) void {
        env.store.close();
        env.arena.deinit();
    }

    fn call(env: *TestEnv, method: http.Method, target: []const u8, body: []const u8) !Response {
        return handle(&env.store, env.arena.allocator(), .{ .method = method, .target = target, .body = body });
    }

    fn expect(env: *TestEnv, method: http.Method, target: []const u8, body: []const u8, status: http.Status, want: ?[]const u8) !void {
        const res = try env.call(method, target, body);
        try testing.expectEqual(status, res.status);
        if (want) |w| try testing.expectEqualStrings(w, res.body);
    }
};

test "routing and status codes" {
    var env: TestEnv = try .init();
    defer env.deinit();

    try env.expect(.GET, "/health", "", .ok, "ok");
    try env.expect(.GET, "/nope", "", .not_found, null);
    try env.expect(.DELETE, "/notes", "", .method_not_allowed, null);
    try env.expect(.POST, "/stats", "", .method_not_allowed, null);
    try env.expect(.GET, "/notes/abc", "", .not_found, null);
    try env.expect(.GET, "/notes/0", "", .not_found, null);
    try env.expect(.GET, "/notes/-1", "", .not_found, null);
    try env.expect(.GET, "/notes/99999999999999999999", "", .not_found, null);
    try env.expect(.POST, "/notes", "{\"title\":\"a b\",\"tags\":[\"z\",\"a\"]}", .created,
        \\{"id":1,"title":"a b","body":"","tags":["a","z"]}
    );
    try env.expect(.GET, "/notes/1?x=1", "", .ok, null);
    try env.expect(.PUT, "/notes/1", "{\"title\":\"\"}", .bad_request, null);
    try env.expect(.PUT, "/notes/2", "{\"title\":\"x\"}", .not_found, null);
    try env.expect(.GET, "/notes?limit=0", "", .bad_request, null);
    try env.expect(.GET, "/notes?limit=101", "", .bad_request, null);
    try env.expect(.GET, "/notes?after=x", "", .bad_request, null);
    try env.expect(.GET, "/notes?q=A+B", "", .ok,
        \\{"notes":[{"id":1,"title":"a b","body":"","tags":["a","z"]}]}
    );
    try env.expect(.GET, "/notes?q=a%20c", "", .ok, "{\"notes\":[]}");
    try env.expect(.GET, "/stats", "", .ok, "{\"notes\":1,\"tags\":{\"a\":1,\"z\":1}}");
    try env.expect(.GET, "/tags", "", .ok,
        \\{"tags":[{"tag":"a","count":1},{"tag":"z","count":1}]}
    );
    try env.expect(.DELETE, "/notes/1", "", .no_content, "");
    try env.expect(.GET, "/stats", "", .ok, "{\"notes\":0,\"tags\":{}}");
}

test parseInteger {
    try testing.expectEqual(-3, parseInteger("-3"));
    try testing.expectEqual(null, parseInteger("+3"));
    try testing.expectEqual(null, parseInteger(""));
    try testing.expectEqual(null, parseInteger("1_0"));
}

//! notes: a small HTTP notes store backed by SQLite.
//!
//! Usage: NOTES_DB=<path> notes <port>

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;
const Store = @import("Store.zig");
const api = @import("api.zig");

/// Largest request body accepted.
const max_body_len = 16 * 1024 * 1024;

const Server = struct {
    gpa: Allocator,
    io: Io,
    store: *Store,
};

pub fn main(init: std.process.Init) !void {
    const gpa = init.gpa;
    const io = init.io;
    const arena = init.arena.allocator();

    const args = try init.minimal.args.toSlice(arena);
    if (args.len != 2) {
        std.log.err("usage: {s} <port>", .{if (args.len > 0) args[0] else "notes"});
        std.process.exit(2);
    }
    const port = std.fmt.parseInt(u16, args[1], 10) catch {
        std.log.err("invalid port: {s}", .{args[1]});
        std.process.exit(2);
    };

    const db_path = try arena.dupeZ(u8, init.environ_map.get("NOTES_DB") orelse "notes.db");
    var store = try Store.open(io, db_path);
    defer store.close();

    const address = try Io.net.IpAddress.parse("127.0.0.1", port);
    var listener = try address.listen(io, .{ .reuse_address = true });
    defer listener.deinit(io);

    var server: Server = .{ .gpa = gpa, .io = io, .store = &store };
    var group: Io.Group = .init;
    defer group.cancel(io);

    while (true) {
        const stream = listener.accept(io) catch |err| {
            std.log.err("accept failed: {t}", .{err});
            continue;
        };
        group.concurrent(io, serveConnection, .{ &server, stream }) catch {
            // No spare thread: serve it on this one rather than dropping it.
            serveConnection(&server, stream);
        };
    }
}

fn serveConnection(server: *Server, stream: Io.net.Stream) void {
    const io = server.io;
    defer stream.close(io);

    var recv_buffer: [8 * 1024]u8 = undefined;
    var send_buffer: [8 * 1024]u8 = undefined;
    var conn_reader = stream.reader(io, &recv_buffer);
    var conn_writer = stream.writer(io, &send_buffer);
    var http_server = std.http.Server.init(&conn_reader.interface, &conn_writer.interface);

    var arena_state: std.heap.ArenaAllocator = .init(server.gpa);
    defer arena_state.deinit();

    while (http_server.reader.state == .ready) {
        _ = arena_state.reset(.retain_capacity);
        var request = http_server.receiveHead() catch |err| switch (err) {
            error.HttpConnectionClosing => return,
            else => {
                std.log.debug("closing connection: {t}", .{err});
                return;
            },
        };
        serveRequest(server, arena_state.allocator(), &request) catch |err| {
            std.log.err("{s} {s}: {t}", .{ @tagName(request.head.method), request.head.target, err });
            return;
        };
    }
}

fn serveRequest(server: *Server, arena: Allocator, request: *std.http.Server.Request) !void {
    const method = request.head.method;
    // Reading the body invalidates the strings in `request.head`.
    const target = try arena.dupe(u8, request.head.target);

    var body: []const u8 = "";
    if (method.requestHasBody()) {
        // HTTP/1.1: a request without Content-Length or Transfer-Encoding has no body.
        if (request.head.content_length == null and request.head.transfer_encoding == .none)
            request.head.content_length = 0;
        const reader = try request.readerExpectContinue(&.{});
        body = reader.allocRemaining(arena, .limited(max_body_len)) catch |err| switch (err) {
            error.StreamTooLong => return respond(request, .{
                .status = .payload_too_large,
                .body = "{\"error\":\"body too large\"}",
            }),
            else => |e| return e,
        };
    }

    const response = api.handle(server.store, arena, .{ .method = method, .target = target, .body = body }) catch |err| blk: {
        std.log.err("{s} {s}: {t}", .{ @tagName(method), target, err });
        break :blk api.Response{ .status = .internal_server_error, .body = "{\"error\":\"internal error\"}" };
    };
    try respond(request, response);
}

fn respond(request: *std.http.Server.Request, response: api.Response) !void {
    const headers: []const std.http.Header = &.{.{ .name = "content-type", .value = response.content_type }};
    try request.respond(response.body, .{
        .status = response.status,
        .extra_headers = if (response.status == .no_content) &.{} else headers,
    });
}

