//! The note model and validation of client-supplied note payloads.

const std = @import("std");
const Allocator = std.mem.Allocator;

pub const Note = struct {
    id: i64,
    title: []const u8,
    body: []const u8,
    tags: []const []const u8,
};

/// A validated note payload: trimmed title, and tags deduplicated and sorted.
pub const Input = struct {
    title: []const u8,
    body: []const u8,
    tags: []const []const u8,
};

pub const max_title_len = 200;
pub const max_tag_len = 32;

/// Result of parsing a payload: either a valid input or a client-facing error message.
pub const ParseResult = union(enum) {
    ok: Input,
    invalid: []const u8,
};

/// Parses and validates a JSON request body. All returned memory is owned by `arena`.
pub fn parseInput(arena: Allocator, json_text: []const u8) Allocator.Error!ParseResult {
    const value = std.json.parseFromSliceLeaky(std.json.Value, arena, json_text, .{
        .duplicate_field_behavior = .use_last,
    }) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        else => return .{ .invalid = "body is not valid JSON" },
    };
    const obj = switch (value) {
        .object => |o| o,
        else => return .{ .invalid = "body must be a JSON object" },
    };

    const title_raw = switch (obj.get("title") orelse return .{ .invalid = "title is required" }) {
        .string => |s| s,
        else => return .{ .invalid = "title must be a string" },
    };
    const title = std.mem.trim(u8, title_raw, " \t\r\n");
    const title_len = std.unicode.utf8CountCodepoints(title) catch title.len;
    if (title_len < 1 or title_len > max_title_len)
        return .{ .invalid = "title must be 1-200 characters" };

    const body: []const u8 = if (obj.get("body")) |v| switch (v) {
        .string => |s| s,
        else => return .{ .invalid = "body must be a string" },
    } else "";

    var tags: []const []const u8 = &.{};
    if (obj.get("tags")) |v| {
        const items = switch (v) {
            .array => |a| a.items,
            else => return .{ .invalid = "tags must be an array of strings" },
        };
        const list = try arena.alloc([]const u8, items.len);
        for (items, list) |item, *slot| {
            slot.* = switch (item) {
                .string => |s| s,
                else => return .{ .invalid = "tags must be an array of strings" },
            };
            if (!isValidTag(slot.*))
                return .{ .invalid = "each tag must be 1-32 characters of a-z, 0-9 and -" };
        }
        tags = sortUnique(list);
    }

    return .{ .ok = .{ .title = title, .body = body, .tags = tags } };
}

pub fn isValidTag(tag: []const u8) bool {
    if (tag.len < 1 or tag.len > max_tag_len) return false;
    for (tag) |ch| switch (ch) {
        'a'...'z', '0'...'9', '-' => {},
        else => return false,
    };
    return true;
}

fn lessThan(_: void, a: []const u8, b: []const u8) bool {
    return std.mem.lessThan(u8, a, b);
}

/// Sorts `list` ascending in place and returns the prefix holding the unique elements.
fn sortUnique(list: [][]const u8) [][]const u8 {
    std.mem.sort([]const u8, list, {}, lessThan);
    var n: usize = 0;
    for (list) |tag| {
        if (n > 0 and std.mem.eql(u8, list[n - 1], tag)) continue;
        list[n] = tag;
        n += 1;
    }
    return list[0..n];
}

const testing = std.testing;

fn expectInvalid(text: []const u8) !void {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    try testing.expect((try parseInput(arena.allocator(), text)) == .invalid);
}

test "parseInput normalizes title and tags" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const r = try parseInput(arena.allocator(),
        \\{"title":"  second  ","body":"some text","tags":["work","b-2","work"]}
    );
    const in = r.ok;
    try testing.expectEqualStrings("second", in.title);
    try testing.expectEqualStrings("some text", in.body);
    try testing.expectEqual(2, in.tags.len);
    try testing.expectEqualStrings("b-2", in.tags[0]);
    try testing.expectEqualStrings("work", in.tags[1]);
}

test "parseInput defaults" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const in = (try parseInput(arena.allocator(), "{\"title\":\"x\"}")).ok;
    try testing.expectEqualStrings("", in.body);
    try testing.expectEqual(0, in.tags.len);
}

test "parseInput rejects invalid payloads" {
    try expectInvalid("{\"title\": ");
    try expectInvalid("");
    try expectInvalid("{\"title\":\"x\"} x");
    try expectInvalid("[]");
    try expectInvalid("{}");
    try expectInvalid("{\"title\":\"   \"}");
    try expectInvalid("{\"title\":5}");
    try expectInvalid("{\"title\":\"x\",\"tags\":[\"Bad\"]}");
    try expectInvalid("{\"title\":\"x\",\"tags\":[\"\"]}");
    try expectInvalid("{\"title\":\"x\",\"tags\":\"a\"}");
    try expectInvalid("{\"title\":\"x\",\"tags\":[1]}");
    try expectInvalid("{\"title\":\"x\",\"body\":3}");
    try expectInvalid("{\"title\":\"x\",\"body\":null}");
    try expectInvalid("{\"title\":\"" ++ "a" ** 201 ++ "\"}");
    try expectInvalid("{\"title\":\"x\",\"tags\":[\"" ++ "a" ** 33 ++ "\"]}");
}

test "title length counts characters, not bytes" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const r = try parseInput(arena.allocator(), "{\"title\":\"" ++ "é" ** 200 ++ "\"}");
    try testing.expect(r == .ok);
}

//! Thin, typed wrapper around the parts of the SQLite C API this service uses.

const std = @import("std");

pub const c = @cImport(@cInclude("sqlite3.h"));

pub const Error = error{Sqlite};

fn check(db: ?*c.sqlite3, rc: c_int) Error!void {
    if (rc == c.SQLITE_OK or rc == c.SQLITE_DONE or rc == c.SQLITE_ROW) return;
    std.log.err("sqlite error {d}: {s}", .{ rc, std.mem.span(c.sqlite3_errmsg(db)) });
    return error.Sqlite;
}

pub const Db = struct {
    handle: *c.sqlite3,

    pub fn open(path: [:0]const u8) Error!Db {
        var handle: ?*c.sqlite3 = null;
        const flags = c.SQLITE_OPEN_READWRITE | c.SQLITE_OPEN_CREATE | c.SQLITE_OPEN_FULLMUTEX;
        const rc = c.sqlite3_open_v2(path.ptr, &handle, flags, null);
        if (rc != c.SQLITE_OK) {
            std.log.err("cannot open database '{s}': {s}", .{ path, c.sqlite3_errstr(rc) });
            if (handle) |h| _ = c.sqlite3_close(h);
            return error.Sqlite;
        }
        return .{ .handle = handle.? };
    }

    pub fn close(db: Db) void {
        _ = c.sqlite3_close(db.handle);
    }

    /// Runs one or more SQL statements that take no parameters and return no rows.
    pub fn exec(db: Db, sql: [:0]const u8) Error!void {
        try check(db.handle, c.sqlite3_exec(db.handle, sql.ptr, null, null, null));
    }

    pub fn prepare(db: Db, sql: []const u8) Error!Stmt {
        var stmt: ?*c.sqlite3_stmt = null;
        try check(db.handle, c.sqlite3_prepare_v2(db.handle, sql.ptr, @intCast(sql.len), &stmt, null));
        return .{ .handle = stmt.?, .db = db.handle };
    }

    /// Number of rows modified by the most recent INSERT, UPDATE or DELETE.
    pub fn changes(db: Db) i64 {
        return c.sqlite3_changes64(db.handle);
    }

    pub fn lastInsertRowId(db: Db) i64 {
        return c.sqlite3_last_insert_rowid(db.handle);
    }
};

pub const Stmt = struct {
    handle: *c.sqlite3_stmt,
    db: *c.sqlite3,

    pub fn finalize(s: Stmt) void {
        _ = c.sqlite3_finalize(s.handle);
    }

    pub fn reset(s: Stmt) Error!void {
        try check(s.db, c.sqlite3_reset(s.handle));
        try check(s.db, c.sqlite3_clear_bindings(s.handle));
    }

    /// Binds `value` to the 1-based parameter `index`. Text is bound without a
    /// copy, so it must outlive the next `step`/`reset`.
    pub fn bind(s: Stmt, index: c_int, value: anytype) Error!void {
        const T = @TypeOf(value);
        const rc = switch (@typeInfo(T)) {
            .int, .comptime_int => c.sqlite3_bind_int64(s.handle, index, @intCast(value)),
            .pointer => blk: {
                const bytes: []const u8 = value;
                break :blk c.sqlite3_bind_text64(s.handle, index, bytes.ptr, bytes.len, null, c.SQLITE_UTF8);
            },
            else => @compileError("unsupported bind type " ++ @typeName(T)),
        };
        try check(s.db, rc);
    }

    /// Binds each element of the tuple `values` to parameters 1, 2, ….
    pub fn bindAll(s: Stmt, values: anytype) Error!void {
        inline for (values, 1..) |v, i| try s.bind(@intCast(i), v);
    }

    /// Advances the statement; returns true when a row is available.
    pub fn step(s: Stmt) Error!bool {
        const rc = c.sqlite3_step(s.handle);
        try check(s.db, rc);
        return rc == c.SQLITE_ROW;
    }

    pub fn int(s: Stmt, col: c_int) i64 {
        return c.sqlite3_column_int64(s.handle, col);
    }

    /// Text of column `col`, valid until the next `step`, `reset` or `finalize`.
    pub fn text(s: Stmt, col: c_int) []const u8 {
        const ptr = c.sqlite3_column_text(s.handle, col) orelse return "";
        const len: usize = @intCast(c.sqlite3_column_bytes(s.handle, col));
        return ptr[0..len];
    }
};

test "open in-memory database and round-trip a row" {
    const db = try Db.open(":memory:");
    defer db.close();
    try db.exec("CREATE TABLE t (a INTEGER, b TEXT)");
    {
        const ins = try db.prepare("INSERT INTO t VALUES (?, ?)");
        defer ins.finalize();
        try ins.bindAll(.{ 42, "hi" });
        try std.testing.expect(!try ins.step());
    }
    const sel = try db.prepare("SELECT a, b FROM t");
    defer sel.finalize();
    try std.testing.expect(try sel.step());
    try std.testing.expectEqual(42, sel.int(0));
    try std.testing.expectEqualStrings("hi", sel.text(1));
    try std.testing.expect(!try sel.step());
}
